1	//! String compare (case-insensitive ASCII) — 1:1 port of the `stricmp` /
2	//! `strnicmp` family in `sqlite-source/src/util.c`.
3	//!
4	//! Source mapping:
5	//! - `sqlite3_stricmp`  (util.c:415-422) — public, case-insensitive full compare
6	//! - `sqlite3StrICmp`   (util.c:423-441) — internal helper, full compare loop
7	//! - `sqlite3_strnicmp` (util.c:442-453) — public, case-insensitive bounded
8	//!   compare (up to N bytes)
9	//!
10	//! The 7-bit ASCII case fold uses the `sqlite3UpperToLower` table defined in
11	//! `sqlite-source/src/global.c:24-41`. The ASCII variant maps
12	//! `0x41..=0x5A` ('A'..'Z') to their lowercase counterparts `0x61..=0x7A`
13	//! ('a'..'z') and leaves every other byte unchanged.
14	//!
15	//! # Behavior contract (matching C)
16	//!
17	//! - `None` arguments model the C `NULL` pointer. The public APIs return:
18	//!   - `stricmp(NULL, NULL) == 0`
19	//!   - `stricmp(NULL, x)   < 0` (specifically `-1`)
20	//!   - `stricmp(x, NULL)   > 0` (specifically ` 1`)
21	//! - Comparison is byte-wise on the supplied `&[u8]` slice. A `0` byte
22	//!   inside the slice is treated as the C NUL terminator — both APIs stop
23	//!   at the first `0` they encounter in either input.
24	//! - Returns a signed `i32` (neg / zero / pos) suitable for feeding back
25	//!   into C-style comparison tables (`sqlite3aLTb` / `aEQb` / `aGTb`).
26	//! - Only the ASCII range is folded; UTF-8 multi-byte sequences pass
27	//!   through verbatim (and a stray `0x00` byte is treated as terminator).
28	//! - `sqlite3_strnicmp` with `N <= 0` returns 0 (loop never enters, the
29	//!   C `N-- > 0` check fails on the first iteration).
30	//! - `sqlite3_strnicmp` with `N` larger than either string's length
31	//!   behaves like `sqlite3_stricmp` — it stops at the first NUL / slice
32	//!   end and returns the byte-wise diff of the first differing position.
33	
34	// ----------------------------------------------------------------------------
35	// sqlite3UpperToLower table (ASCII variant from global.c:24-41)
36	// ----------------------------------------------------------------------------
37	
38	/// 256-byte ASCII case-fold table — equivalent of `sqlite3UpperToLower`.
39	///
40	/// Indexing `UPPER_TO_LOWER[b as usize]` returns `b` with the ASCII
41	/// uppercase range `0x41..=0x5A` mapped to lowercase `0x61..=0x7A`. All
42	/// other byte values are identity.
43	const UPPER_TO_LOWER: [u8; 256] = {
44	    let mut t = [0u8; 256];
45	    let mut i: usize = 0;
46	    while i < 256 {
47	        t[i] = if i >= 0x41 && i <= 0x5A { (i + 32) as u8 } else { i as u8 };
48	        i += 1;
49	    }
50	    t
51	};
52	
53	/// Apply the `sqlite3UpperToLower` fold to a single byte.
54	#[inline]
55	fn to_lower(b: u8) -> u8 {
56	    // SAFETY: `b as usize` is in `0..=255`, so the index is in-bounds for
57	    // the 256-entry table. `UPPER_TO_LOWER` is a `const` array stored in
58	    // static memory; indexing it does not require `unsafe`.
59	    UPPER_TO_LOWER[b as usize]
60	}
61	
62	// ----------------------------------------------------------------------------
63	// sqlite3StrICmp — internal full-length case-insensitive compare
64	// (util.c:423-441)
65	// ----------------------------------------------------------------------------
66	
67	/// Internal case-insensitive full compare over two byte slices, treating
68	/// a `0` byte as the string terminator (matching the C `char*` semantics
69	/// used by the original `sqlite3StrICmp`).
70	///
71	/// The return value is the byte-wise difference of the first differing
72	/// position after ASCII case-folding, or `0` if the two strings are
73	/// equal up to the first NUL / slice end.
74	///
75	/// Translation of the C reference (util.c:423-441):
76	/// ```c
77	/// for(;;){
78	///     c = *a;  x = *b;
79	///     if( c==x ){
80	///         if( c==0 ) break;        // both NUL → equal
81	///     }else{
82	///         c = (int)UpperToLower[c] - (int)UpperToLower[x];
83	///         if( c ) break;            // folded diff non-zero → return diff
84	///         // else: case pair ('A' vs 'a') → fall through, advance
85	///     }
86	///     a++;  b++;
87	/// }
88	/// return c;
89	/// ```
90	pub fn str_icmp(a: &[u8], b: &[u8]) -> i32 {
91	    let mut i: usize = 0;
92	    loop {
93	        // Treat the end of either slice as an implicit NUL terminator —
94	        // mirrors C's NUL-terminated `char*` reads.
95	        let ca = if i < a.len() { a[i] } else { 0 };
96	        let cb = if i < b.len() { b[i] } else { 0 };
97	        if ca == cb {
98	            if ca == 0 {
99	                // Both strings ended together — equal.
100	                return 0;
101	            }
102	            // Raw bytes match (and are non-NUL) — advance.
103	        } else {
104	            let diff = (to_lower(ca) as i32) - (to_lower(cb) as i32);
105	            if diff != 0 {
106	                // Folded bytes differ — return the post-fold difference.
107	                // NOTE: this is `c` from the C code (overloaded), which
108	                // is now the folded diff, not the raw byte.
109	                return diff;
110	            }
111	            // Case pair (e.g. 'A' vs 'a') folded to the same byte; the C
112	            // code does NOT break here (the `if( c ) break` is false when
113	            // c == 0). It falls through to `a++; b++;` and continues.
114	            // Translating 1:1: just advance, do not return.
115	        }
116	        i += 1;
117	    }
118	}
119	
120	// ----------------------------------------------------------------------------
121	// sqlite3_stricmp — public case-insensitive full compare
122	// (util.c:415-422)
123	// ----------------------------------------------------------------------------
124	
125	/// Public case-insensitive UTF-8 string compare (1:1 port of
126	/// `sqlite3_stricmp` from `util.c:415-422`).
127	///
128	/// `None` models the C `NULL` pointer:
129	/// - `(None, None)` → `0`
130	/// - `(None, Some(_))` → `-1`
131	/// - `(Some(_), None)` → ` 1`
132	///
133	/// Otherwise the function returns the signed difference of the first
134	/// differing byte after ASCII case-folding (`< 0` if `z_left < z_right`,
135	/// `> 0` if `z_left > z_right`, `0` if equal).
136	///
137	/// Note: a `0` byte inside either slice is treated as the string
138	/// terminator, matching the C `char*` semantics.
139	pub fn sqlite3_stricmp(z_left: Option<&[u8]>, z_right: Option<&[u8]>) -> i32 {
140	    match (z_left, z_right) {
141	        (None, None) => 0,
142	        (None, Some(_)) => -1,
143	        (Some(_), None) => 1,
144	        (Some(l), Some(r)) => str_icmp(l, r),
145	    }
146	}
147	
148	// ----------------------------------------------------------------------------
149	// sqlite3_strnicmp — public case-insensitive bounded compare
150	// (util.c:442-453)
151	// ----------------------------------------------------------------------------
152	
153	/// Public case-insensitive compare of at most `n` bytes (1:1 port of
154	/// `sqlite3_strnicmp` from `util.c:442-453`).
155	///
156	/// NULL handling mirrors `sqlite3_stricmp`:
157	/// - `(None, None)` → `0`
158	/// - `(None, Some(_))` → `-1`
159	/// - `(Some(_), None)` → ` 1`
160	///
161	/// Non-NULL inputs:
162	/// - `n <= 0` → returns `0` (the C `while (N-- > 0 ...)` never enters)
163	/// - Walks both strings in lockstep, stopping when:
164	///   1. `n` iterations have been performed, OR
165	///   2. a `0` byte is seen in `z_left` (NUL terminator), OR
166	///   3. the ASCII-folded bytes differ
167	/// - If `n` iterations completed, returns `0` (this matches the C
168	///   `return N<0 ? 0 : ...` — once we have compared the full budget
169	///   the C code declares the strings equal regardless of what comes
170	///   after).
171	/// - Otherwise returns the byte-wise difference of the current
172	///   positions after ASCII case-folding.
173	pub fn sqlite3_strnicmp(z_left: Option<&[u8]>, z_right: Option<&[u8]>, n: i32) -> i32 {
174	    match (z_left, z_right) {
175	        (None, None) => 0,
176	        (None, Some(_)) => -1,
177	        (Some(_), None) => 1,
178	        (Some(a), Some(b)) => {
179	            let mut remaining = n;
180	            let mut i: usize = 0;
181	            loop {
182	                if remaining <= 0 {
183	                    break;
184	                }
185	                let ca = if i < a.len() { a[i] } else { 0 };
186	                if ca == 0 {
187	                    // NUL in `a` — C exits the loop here before the
188	                    // case-folded comparison, then returns
189	                    // `UpperToLower[*a] - UpperToLower[*b]` below.
190	                    break;
191	                }
192	                let cb = if i < b.len() { b[i] } else { 0 };
193	                if to_lower(ca) != to_lower(cb) {
194	                    break;
195	                }
196	                i += 1;
197	                remaining -= 1;
198	            }
199	            if remaining <= 0 {
200	                // The C code returns 0 here (`N<0`) only if N became
201	                // negative during the post-decrement in the loop header.
202	                // In our formulation `remaining` is decremented AFTER
203	                // the work, so we mirror by checking `remaining <= 0`
204	                // which captures both "N=0 initially" and "N iterations
205	                // completed exactly".
206	                0
207	            } else {
208	                let ca = if i < a.len() { a[i] } else { 0 };
209	                let cb = if i < b.len() { b[i] } else { 0 };
210	                (to_lower(ca) as i32) - (to_lower(cb) as i32)
211	            }
212	        }
213	    }
214	}
