mod tests {
    use super::*;

    #[test]
    fn internal_str_icmp_equal() {
        assert_eq!(str_icmp(b"hello", b"hello"), 0);
    }

    #[test]
    fn internal_str_icmp_case_diff_returns_zero() {
        // Case-fold makes 'A' and 'a' equal — diff is 0.
