        assert_eq!(sqlite3_stricmp(None, None), 0);
        assert_eq!(sqlite3_stricmp(None, Some(b"x")), -1);
        assert_eq!(sqlite3_stricmp(Some(b"x"), None), 1);
    }

    #[test]
